css:
.page {
  display: grid;
  gap: 16px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.crumbs {
  display: flex;
  gap: 8px;
}

.crumb {
  color: #c2410c;
}

.crumb:not(:last-child)::after {
  content: "/";
  display: inline-block;
  margin-left: 8px;
  color: #a1a1aa;
}

.cards {
  display: grid;
  gap: 12px;
}

.card {
  display: grid;
  gap: 12px;
  padding: 12px;
  border: 1px solid #e4e4e7;
  border-radius: 10px;
}

.card:has(.card-img) {
  display: grid;
  grid-template-columns: 96px 1fr;
  align-items: center;
}

.card-img {
  width: 96px;
  height: 64px;
  border-radius: 6px;
  object-fit: cover;
}

.card-text {
  margin: 0;
}

.field {
  display: grid;
  gap: 6px;
  padding: 12px;
  border: 2px solid #e4e4e7;
  border-radius: 10px;
}

.field:has(input:focus) {
  border-color: #f97316;
  background-color: #fff7ed;
}

.field input {
  padding: 8px;
  border: 1px solid #d4d4d8;
  border-radius: 6px;
  font: inherit;
}
